"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[6743],{900:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"Sprint 4","metadata":{"permalink":"/microsite/blog/Sprint 4","source":"@site/blog/sprint4/sprint_4.md","title":"Sprint 4","description":"From: 2026-02-09","date":"2026-03-17T00:16:28.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"Sprint 4","title":"Sprint 4"},"unlisted":false,"nextItem":{"title":"Sprint 3","permalink":"/microsite/blog/Sprint 3"}},"content":"**From**: 2026-02-09\\n\\n**To**: 2026-03-17\\n\\n**Scrum Master**: Catarina Ribeiro\\n\\n**Product Owner**: IEETA\\n\\n**Developers**: Marta Cruz, Beatriz Francisco, Matilde Rodrigues, Catarina Ribeiro\\n\\nIn this sprint, we continued the work from last semester, starting to implement more features with special attention to usability and accessibility, which are the main goals for the first milestone of this semester.\\n\\n- Dark mode\\n- Color blind mode\\n- Text-to-speech\\n- System security improvement\\n- Data analysis integration\\n- Data analysis alerts integration\\n- Goals and Gamification \\n- Keycloak implementation\\n- Usability tests and SUS analysis\\n- Frontend refactoring\\n- Update Microsite\\n\\n| Expected     | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 11       |\\n| Story Points | 70       |\\n\\n## Sprint Backlog\\n\\n| Task (KAN-\\\\*) | Description                 | Developer                                      | State | Story Points |\\n| --------------- | --------------------------- | ---------------------------------------------- | ----- | ------------ |\\n| KAN-25        | Dark mode        | Catarina Ribeiro                       | Done  | 5          |\\n| KAN-26        | Color blind mode | Catarina Ribeiro                       | Done  | 5          |\\n| KAN-27        | Text-to-speech   | Catarina Ribeiro                       | Done  | 5          |\\n| KAN-28        | System security improvement  | Marta Cruz                 | Done  | 5          |\\n| KAN-29        | Data analysis integration | Beatriz Francisco             | Done  | 10         |\\n| KAN-30        | Data analysis alerts integration       | Mariana Marques  | Done  | 10         |\\n| KAN-31        | Goals and Gamification  | Matilde Rodrigues               | Done  | 10         |\\n| KAN-32        | Keycloak implementation | Marta Cruz                      | Not Done  | 5      |\\n| KAN-33        | Usability tests and SUS analysis | Catarina Ribeiro and Marta Cruz            | Done  | 5            |\\n| KAN-34        | Frontend refactoring | Catarina Ribeiro                   | Done  | 5          |\\n| KAN-16        | Update Microsite            | Catarina Ribeiro            | Done  | 5          |\\n\\n### Task Status (Completed/Not Completed)\\n\\n- [x] KAN-25: Dark mode\\n- [x] KAN-26: Color blind mode\\n- [x] KAN-27: Text-to-Speech\\n- [x] KAN-28: System security improvement\\n- [x] KAN-29: Data analysis integration\\n- [x] KAN-30: Data analysis alerts integration\\n- [x] KAN-31: Goals and Gamification \\n- [ ] KAN-32: Keycloak implementation\\n- [x] KAN-33: Usability tests and SUS analysis\\n- [x] KAN-34: Frontend refactoring\\n- [x] KAN-16: Update Microsite\\n\\n## Sprint Review\\n\\n| Concluded    | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 10       |\\n| Story Points | 65       |\\n\\n## Sprint Retrospective\\n\\nThis sprint was focused and productive, with the team making significant progress on usability and accessibility features. The implementation of dark mode, color blind mode, and text-to-speech functionality marked important steps toward a more inclusive user experience, while the frontend refactoring helped improve the overall code maintainability. Although Keycloak was not completed, this task was intentionally started ahead of schedule and will be finalized in the next sprint as planned. Overall, the team delivered 10 out of 11 tasks, successfully achieving the sprint\'s core objectives.\\n\\n\x3c!-- truncate --\x3e`"},{"id":"Sprint 3","metadata":{"permalink":"/microsite/blog/Sprint 3","source":"@site/blog/sprint3/sprint_3.md","title":"Sprint 3","description":"From: 2025-11-19","date":"2025-12-16T22:29:37.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"Sprint 3","title":"Sprint 3"},"unlisted":false,"prevItem":{"title":"Sprint 4","permalink":"/microsite/blog/Sprint 4"},"nextItem":{"title":"Sprint 2","permalink":"/microsite/blog/Sprint 2"}},"content":"**From**: 2025-11-19\\n\\n**To**: 2025-12-16\\n\\n**Scrum Master**: Beatriz Francisco\\n\\n**Product Owner**: IEETA\\n\\n**Developers**: Marta Cruz, Beatriz Francisco, Matilde Rodrigues, Catarina Ribeiro\\n\\nIn this sprint, we aimed to finish all tasks related to the MVP for the milestone 3 and also an extra task that was not planned for this semester. \\n\\n- Setup all four databases\\n- Complete backend API implementation\\n- Full Frontend-Backend API integration\\n- 3D Avatar & Data Simulation on Frontend\\n- Live Sensor Integration & Real-time Visualization\\n- Setup LaTeX Report\\n- Preparation for Third Presentation\\n- Update Microsite\\n\\n| Expected     | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 8        |\\n| Story Points | 40       |\\n\\n## Sprint Backlog\\n\\n| Task (KAN-\\\\*) | Description                 | Developer                                      | State | Story Points |\\n| --------------- | --------------------------- | ---------------------------------------------- | ----- | ------------ |\\n| KAN-18        | Setup all four databases   | Mariana Marques e Beatriz Francisco              | Done  | 5            |\\n| KAN-19        | Complete backend API implementation |  Catarina Ribeiro, Mariana Marques and Marta Cruz| Done  | 5            |\\n| KAN-20        | Full Frontend-Backend API integration| All                                   | Done  | 5            |\\n| KAN-21        | 3D Avatar & Data Simulation on Frontend | Beatriz Francisco                  | Done  | 5            |\\n| KAN-22        | Live Sensor Integration & Real-time Visualization | Marta Cruz Francisco                           | Done  | 5            |\\n| KAN-23        | Setup LaTeX Report         | Matilde Rodrigues                              | Done  | 5            |\\n| KAN-24        | Preparation for Third Presentation | All                                     | Done  | 5            |\\n| KAN-16        | Update Microsite            | Catarina Ribeiro                               | Done  | 5            |\\n\\n### Task Status (Completed/Not Completed)\\n\\n- [x] KAN-18: Setup all four databases\\n- [x] KAN-19: Complete backend API implementation\\n- [x] KAN-20: Full Frontend-Backend API integration\\n- [x] KAN-21: 3D Avatar & Data Simulation on Frontend\\n- [x] KAN-22: Live Sensor Integration & Real-time Visualization\\n- [x] KAN-23: Setup LaTeX Report\\n- [x] KAN-24: Preparation for Third Presentation\\n- [x] KAN-16: Update Microsite\\n\\n## Sprint Review\\n\\n| Concluded    | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 8        |\\n| Story Points | 40       |\\n\\n## Sprint Retrospective\\n\\nThis sprint was intense but highly productive. The team successfully delivered all core components of Milestone 3, transforming the project from a conceptual model into a working prototype. The integration of the live sensor with the 3D visualization was a particular highlight and a significant technical success.\\n\\n\x3c!-- truncate --\x3e`"},{"id":"Sprint 2","metadata":{"permalink":"/microsite/blog/Sprint 2","source":"@site/blog/sprint2/sprint_2.md","title":"Sprint 2","description":"From: 2025-10-28","date":"2025-11-17T12:56:38.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"Sprint 2","title":"Sprint 2"},"unlisted":false,"prevItem":{"title":"Sprint 3","permalink":"/microsite/blog/Sprint 3"},"nextItem":{"title":"Sprint 1","permalink":"/microsite/blog/Sprint 1"}},"content":"**From**: 2025-10-28\\n\\n**To**: 2025-11-18\\n\\n**Scrum Master**: Marta Cruz\\n\\n**Product Owner**: IEETA\\n\\n**Developers**: Marta Cruz, Beatriz Francisco, Matilde Rodrigues, Catarina Ribeiro\\n\\nIn this sprint, we aimed to finish all the tasks that were not possible to complete in the previous sprint and since we had already completed most of the goals for milestone 2 in the previous sprint, we also started to advance work towards milestone 3:\\n\\n- UI Mockups\\n- Technology Stack\\n- Schemas and Models for all Databases\\n- Script to generate sensor data\\n- Setup all Frontend\\n- Update Microsite\\n- Update all the documentation\\n- Preparation for Second Presentation\\n\\n| Expected     | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 8        |\\n| Story Points | 40       |\\n\\n## Sprint Backlog\\n\\n| Task (KAN-\\\\*) | Description                 | Developer                                      | State | Story Points |\\n| --------------- | --------------------------- | ---------------------------------------------- | ----- | ------------ |\\n| KAN-9         | UI Mockups                  | Catarina Ribeiro                               | Done  | 5            |\\n| KAN-10        | Technologies                | Marta Cruz                                     | Done  | 5            |\\n| KAN-11        | Update Documentation        | All                                            | Done  | 5            |\\n| KAN-13        | Schemas and Models for all Databases | Marta Cruz and Mariana Marques        | Done  | 5            |\\n| KAN-14        | Script to generate sensor data | Beatriz Francisco and Matilde Rodrigues     | Done  | 5            |\\n| KAN-15        | Setup all Frontend          | Mariana Marques and Catarina Ribeiro           | Done  | 5            |\\n| KAN-16        | Update Microsite            | Catarina Ribeiro                               | Done  | 5            |\\n| KAN-17        | Preparation for Second Presentation | Matilde Rodrigues and Beatriz Francisco   | Done  | 5            |\\n\\n### Task Status (Completed/Not Completed)\\n\\n- [x] KAN-9: UI Mockups\\n- [x] KAN-10: Technologies\\n- [x] KAN-11: Update Documentation\\n- [x] KAN-13: Schemas and Models for all Databases\\n- [x] KAN-14: Script to generate sensor data\\n- [x] KAN-15: Setup all Frontend\\n- [x] KAN-16: Update Microsite\\n- [x] KAN-17: Preparation for Second Presentation\\n\\n## Sprint Review\\n\\n| Concluded    | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 8        |\\n| Story Points | 40       |\\n\\n## Sprint Retrospective\\n\\nIn this sprint, we managed to complete all the tasks that were planned. The team worked well together and managed to finish the sprint goals on time.\\n\\n\x3c!-- truncate --\x3e`"},{"id":"Sprint 1","metadata":{"permalink":"/microsite/blog/Sprint 1","source":"@site/blog/sprint1/sprint_1.md","title":"Sprint 1","description":"From: 2025-09-29","date":"2025-10-19T22:57:07.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"Sprint 1","title":"Sprint 1"},"unlisted":false,"prevItem":{"title":"Sprint 2","permalink":"/microsite/blog/Sprint 2"}},"content":"**From**: 2025-09-29\\n\\n**To**: 2025-10-28\\n\\n**Scrum Master**: Mariana Marques\\n\\n**Product Owner**: IEETA\\n\\n**Developers**: Marta Cruz, Beatriz Francisco, Matilde Rodrigues, Catarina Ribeiro\\n## Sprint Goal\\n\\nIn order to complete the first milestone of our project, it is expectable to conclude the following sprints goals:\\n\\n- Functional requirements\\n- Non-functional requirements\\n- Personas\\n- Use Cases\\n- User Stories\\n- UI Mockups\\n- Architecture and Design\\n- Technology Stack\\n- State of the Art\\n- Creat Microsite\\n- Update all the documentation\\n- Presentation Preparation\\n\\n| Expected     | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 12       |\\n| Story Points | 60       |\\n\\n## Sprint Backlog\\n\\n| Task (KAN-\\\\*) | Description                 | Developer                                      | State | Story Points |\\n| --------------- | --------------------------- | ---------------------------------------------- | ----- | ------------ |\\n| KAN-1         | State of the Art            | Beatriz Francisco                              | Done  | 5            |\\n| KAN-2         | Functional Requirements     | Mariana Marques                                | Done  | 5            |\\n| KAN-3         | Non-functional Requirements | Mariana Marques                                | Done  | 5            |\\n| KAN-4         | Personas                    | All                                            | Done  | 5            |\\n| KAN-5         | Use Cases                   | Mariana Marques and Beatriz Francisco          | Done  | 5            |\\n| KAN-6         | User Stories                | Matilde Rodrigues and Mariana Marques          | Done  | 5            |\\n| KAN-7         | Architecture and design     | Marta Cruz                                     | Done  | 5            |\\n| KAN-8         | Creat Microsite             | Catarina Ribeiro                               | Done  | 5            |\\n| KAN-9         | UI Mockups                  | Marta Cruz and Catarina Ribeiro                | Not Done  | 5        |\\n| KAN-10        | Technologies                | All                                            | Not Done  | 5        |\\n| KAN-11        | Update Documentation        | All                                            | Done  | 5            |\\n| KAN-12        | Presentation Preparatiion   | Matilde Rodrigues, Beatriz Francisco and Catarina Ribeiro  | Done  | 5  |\\n\\n### Task Status (Completed/Not Completed)\\n\\n- [x] KAN-1: State of the Art\\n- [x] KAN-2: Functional Requirements\\n- [x] KAN-3: Non-functional Requirements\\n- [x] KAN-4: Personas and \\n- [x] KAN-5: Use Cases\\n- [x] KAN-6: User Stories\\n- [x] KAN-7: Architecture\\n- [x] KAN-8: Creat Microsite\\n- [ ] KAN-9: UI Mockups\\n- [ ] KAN-10: Technologies\\n- [x] KAN-11: Update Documentation\\n- [x] KAN-12: Presentation Preparatiion\\n\\n## Sprint Review\\n\\n| Concluded    | Quantity |\\n| ------------ | -------- |\\n| Tasks        | 10       |\\n| Story Points | 50       |\\n\\n## Sprint Retrospective\\n\\nThis sprint saw substantial completion of tasks including UI mockups and updating project documentation. However, not all mockups were finalized, as only a few were required at this stage to support ongoing development. The remaining mockups will be created in future sprints as the design evolves and additional features are defined. Deciding which technologies to use was also delayed due to limited time and the need to prioritize other critical development tasks. Moving forward, the team plans to dedicate more time to technologies and design updates in upcoming sprints to ensure all project materials remain complete and aligned with progress.\\n\\n\x3c!-- truncate --\x3e`"}]}}')}}]);